export function theAccount(input: {
  account: AssetAccount;
  transactions: any[];
}): TheAccount

export function theNetWorth(input: {
  uid: string;
  accounts: AssetAccount[];
  debts: Debt[];
  /** The recorded history, for the line and the return. */
  monthlyHistory?: Record<string, unknown> | null;
  dailyNetWorth?: Record<string, unknown> | null;
  /** The daily record of what each account was worth, and every record of money moving — what the
   *  return on cash + investments is measured from. */
  snapshotDays?: any[] | null;
  transactions?: any[] | null;
  /** The day a change is measured FROM. With none, the change figures refuse. */
  since?: string | null;
  /** Today, as a day. The screen's own day when it gives one. */
  today?: string;
}): TheNetWorth

export function theEmergencyFund(input: {
  accounts: AssetAccount[];
  expenses: any[];
  profile: any;
  /** The debts, so their minimums are counted. Missing means none entered, not none owed. */
  debts?: Debt[];
  /** Stress test lets a person TRY a cash figure of their own. It is seeded from their real cash and
   *  editable, so the door takes what they typed and answers about that — the arithmetic is the same
   *  question, asked of a number they chose. Absent, the answer is about the cash they actually have. */
  cashOverride?: number;
  /** Job safety lets a person TYPE what a typical month of essentials comes to. Given, it stands in
   *  for the whole month — exactly as it did when that screen multiplied it out for itself. */
  essentialsOverride?: number;
}): EmergencyFund

export function theHolding(input: {
  position: Position;
  accountId: string;
  price: number | null;
  transactions: any[];
  now?: Date;
  /** The recent daily closes, oldest first. Two are enough for the day's change. */
  recentCloses?: number[];
}): HoldingAnswer

export function theLookBack(input: {
  amount: number;
  /** The price history of the fund it is in, and of the one it might have moved to. */
  fromSeries: any;
  toSeries: any;
  months: number;
  now?: Date;
}): LookBackResult | null

export function thePerformance(input: {
  /** The window's first day, or null for "since the record began". */
  windowStart: string | null;
  /** The words for that window, as the screen says them ("since Jul 19"). */
  windowLabel: string;
  today: string;
  /** What the measured accounts are worth now — used ONLY when no accounts are handed over. With
   *  accounts, the function reads it from them, so no two screens can hand it two different figures. */
  ending?: number;
  /** Every record, unfiltered — the door takes the window's own. */
  transactions: any[];
  /** The daily record, and which accounts count as investments. */
  snapshotDays: any[];
  investmentAccountIds: Set<string>;
  /** What the priced holdings gained over the window — used ONLY to derive a beginning the record
   *  cannot reach. It never becomes the return. Null = a holding's gain cannot be known (DEC-3656).
   *  A caller that hands over `holdings` instead lets the door calculate it with the window's own years. */
  pricedGain?: number | null;
  /** The holdings themselves (rows of buildPerformance, or GainRows) — preferred to `pricedGain`, so the
   *  ONE rule (pricedGainOf) decides each holding's gain over THIS window, and the refusal can name the
   *  ones it cannot know. (DEC-3656, 2026-10-09) */
  holdings?: GainRow[];
  /** True for "Since" — the whole record. Its return is the window's OWN total and is never turned
   *  into a yearly rate (Performance v17, phone 3: "Since Jun 3, 2024 +16.24% … not a yearly rate").
   *  A fixed window longer than a year (2Y) still shows the yearly rate. */
  wholeRecord?: boolean;
  /** The accounts as they stand now. Today's values are read from them, so the last day of the
   *  return is measured the same way every recorded day was — and an account added today is seen
   *  as arriving today, not as a gain. */
  accounts?: any[];
}): WindowFigures
